# Terraform: SageMaker Data Quality Job Definition with inter-container traffic encryption enabled
resource "aws_sagemaker_data_quality_job_definition" "example" {
  name     = "<job_definition_name>"
  role_arn = "<role_arn>"

  data_quality_app_specification {
    image_uri = "<image_uri>"
  }

  data_quality_job_input {
    endpoint_input {
      endpoint_name = "<endpoint_name>"
      local_path    = "/opt/ml/processing/input"
    }
  }

  data_quality_job_output_config {
    monitoring_outputs {
      s3_output {
        s3_uri     = "s3://<bucket>/<prefix>"
        local_path = "/opt/ml/processing/output"
      }
    }
  }

  job_resources {
    cluster_config {
      instance_count    = 1
      instance_type     = "ml.m5.large"
      volume_size_in_gb = 20
    }
  }

  network_config {
    enable_inter_container_traffic_encryption = true # CRITICAL: Enables encryption for inter-container communication
  }
}
```
